-- Run once on existing Milestone 2 MySQL database.
ALTER TABLE doctors ADD COLUMN timezone VARCHAR(64) NOT NULL DEFAULT 'Asia/Kolkata', ADD COLUMN languages VARCHAR(200) NULL, ADD COLUMN photo_key VARCHAR(300) NULL;
CREATE TABLE IF NOT EXISTS consultation_types (consultation_type_id CHAR(36) PRIMARY KEY,doctor_id BIGINT UNSIGNED NOT NULL,name ENUM('QUICK','STANDARD','DETAILED','HEALTH_CAMP') NOT NULL,duration_min SMALLINT NOT NULL,fee_amount DECIMAL(10,2) NOT NULL,capacity TINYINT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,UNIQUE KEY uq_doctor_type(doctor_id,name),FOREIGN KEY(doctor_id) REFERENCES doctors(user_id));
CREATE TABLE IF NOT EXISTS availability_patterns (pattern_id CHAR(36) PRIMARY KEY,doctor_id BIGINT UNSIGNED NOT NULL,consultation_type_id CHAR(36) NOT NULL,day_of_week TINYINT NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,KEY ix_doctor_weekday(doctor_id,day_of_week),FOREIGN KEY(doctor_id) REFERENCES doctors(user_id),FOREIGN KEY(consultation_type_id) REFERENCES consultation_types(consultation_type_id));
CREATE TABLE IF NOT EXISTS blackout_dates (blackout_id CHAR(36) PRIMARY KEY,doctor_id BIGINT UNSIGNED NOT NULL,blackout_date DATE NOT NULL,reason VARCHAR(200),UNIQUE KEY uq_doctor_blackout(doctor_id,blackout_date),FOREIGN KEY(doctor_id) REFERENCES doctors(user_id));
